import itertools
from pysat.solvers import Glucose3

def solve_for_n(n):
    solver = Glucose3()
    edge_to_idx = {}
    idx = 1
    for i in range(n):
        for j in range(i + 1, n):
            edge_to_idx[(i, j)] = idx
            idx += 1

    # No red K_4: For every subset of 4 vertices, at least one edge is blue (1).
    for nodes in itertools.combinations(range(n), 4):
        clause = []
        for i, j in itertools.combinations(nodes, 2):
            clause.append(edge_to_idx[tuple(sorted((i, j)))])
        solver.add_clause(clause)

    # No blue K_3: For every subset of 3 vertices, at least one edge is red (0).
    for nodes in itertools.combinations(range(n), 3):
        clause = []
        for i, j in itertools.combinations(nodes, 2):
            clause.append(-edge_to_idx[tuple(sorted((i, j)))])
        solver.add_clause(clause)

    if solver.solve():
        return solver.get_model()
    else:
        return None

print(f"K_8: {solve_for_n(8)}")
print(f"K_9: {solve_for_n(9)}")
